          '<b>定律二 · 高度决定律：</b>连板高度是情绪的温度计。高度向上突破 = 主升；高度逐级塌陷 = 退潮。',
          '<b>定律三 · 传导律：</b>情绪永远从高标传导到中位，再传导到低位；退潮时杀戮顺序同样是<b>高标 → 中位 → 低位</b>（但中位最惨，见中位股章节）。',
          '<b>定律四 · 补涨终结律：</b>当主线内最边缘、最不纯正的票都涨停了（补涨到位），说明主线已无增量资金，顶部临近。',
          '<b>定律五 · 恐高-寻低律：</b>高标越高，资金越恐高，就越会去挖掘低位补涨。补涨潮出现 = 主线进入中后段，而非初段。',
          '<b>定律六 · 中军不死律：</b>主线中军（大市值趋势核心）不破位，主线就不算死亡。中军的走势领先于板块情绪 1-2 天。',
          '<b>定律七 · 分歧位次律：</b>分歧发生在越低的板位越良性，越高的板位越恶性；第一次分歧比第二次第三次安全。',
